fun handleRefund(cmd: RefundCommand): RefundOutcome {
    val payment = payments.find(cmd.paymentId)            // 1. load
        ?: return RefundOutcome.NotFound(cmd.paymentId)
    if (payment.status != Status.CAPTURED)                // 2. check the rule
        return RefundOutcome.NotRefundable(payment.id, payment.status)
    val refundId = gateway.refund(payment.id, cmd.amount) // 3. act
        ?: return RefundOutcome.Rejected(payment.id)
    return RefundOutcome.Accepted(refundId)               // 4. the happy path, last
}

